import React, { useState, useEffect } from 'react';

function App() {
  // Khai báo state để lưu trữ dữ liệu API
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true); // Để theo dõi trạng thái tải dữ liệu

  useEffect(() => {
    // Gọi API khi component được render
    fetch('http://localhost:3000/api/data')  // Đảm bảo URL API chính xác
      .then((response) => response.json())  // Chuyển dữ liệu về dạng JSON
      .then((data) => {
        setData(data);  // Lưu dữ liệu vào state
        setLoading(false);  // Đánh dấu hoàn thành tải dữ liệu
      })
      .catch((error) => {
        console.error('Error fetching data:', error);
        setLoading(false); // Dừng trạng thái tải khi có lỗi
      });
  }, []);  // [] để chỉ chạy useEffect khi component lần đầu render

  return (
    <div>
      <h1>Hello World</h1>
      {/* Hiển thị thông báo khi đang tải */}
      {loading ? (
        <p>Loading...</p>
      ) : (
        // Nếu có dữ liệu, hiển thị nó
        <pre>{JSON.stringify(data, null, 2)}</pre>
      )}
    </div>
  );
}

export default App;
